/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/*
  Original version by Dave Wonnacott at Haverford College <davew@cs.haverford.edu>,
  with help from Allison Lake, Ting Zhou, and Tian Jin,
  based on algorithm by Nussinov, described in Allison Lake's senior thesis.
*/
static
void kernel_nussinov[[gnu::flatten, gnu::noinline]](int n, base POLYBENCH_1D(seq,N,n),
			   DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  /* Use explicit local aliases with restrict-qualified pointers to
     help the optimizer.  seq and table are allocated disjointly in
     main(), so these assumptions are valid. */
  const int N = n;
  base *restrict s = seq;
  DATA_TYPE (*restrict T)[N] = (DATA_TYPE (*restrict)[N])table;

  /* --------------------------------------------------------------
   * Precompute base-pairing compatibility.
   *
   * match(b1,b2) is extremely cheap, but it is executed inside the
   * O(N^3) DP.  We move this O(N^2) work into a separate pass and
   * store the results in a compact N×N unsigned-char matrix:
   *
   *   can_pair[i*N + j] = 1  if  j > i+1  and  seq[i]+seq[j] == 3
   *                      = 0  otherwise
   *
   * This:
   *   - removes the match() call from the DP inner loops,
   *   - makes the DP body smaller and more vectorization-friendly.
   *
   * If allocation fails, we fall back to computing match() on the fly.
   * -------------------------------------------------------------- */
  unsigned char *restrict can_pair =
      (unsigned char *)malloc((size_t)N * (size_t)N * sizeof(unsigned char));

  if (can_pair != NULL)
  {
    for (int i = 0; i < N; ++i) {
      base si = s[i];
      unsigned char *row = can_pair + (size_t)i * (size_t)N;

      /* For j <= i+1 we never allow pairing (diagonal, lower triangle,
         and adjacent bases), so we can set those entries to 0 directly. */
      int j = 0;
      int limit = i + 1;
      if (limit >= N)
        limit = N - 1;

      for (; j <= limit; ++j)
        row[j] = 0u;

      for (; j < N; ++j) {
        /* Here j > i+1 holds by construction. */
        row[j] = (unsigned char)((si + s[j]) == 3 ? 1u : 0u);
      }
    }
  }

  /* --------------------------------------------------------------
   * Dynamic programming kernel.
   *
   * We reformulate the original nested loops in terms of the
   * subsequence length d = j - i (a "band" index), and iterate
   * bands in increasing order:
   *
   *   for d = 1 .. N-1
   *     for i = 0 .. N-d-1
   *       j = i + d
   *
   * For each (i,j) we compute:
   *
   *   best = max(
   *            table[i, j-1],                 // j unpaired
   *            table[i+1, j],                 // i unpaired
   *            table[i+1, j-1] + pair(i,j),   // non-adjacent pair
   *            max_k table[i, k] + table[k+1, j]   // bifurcation
   *          )
   *
   * This order strictly respects all dependencies, and all cells on
   * the same band d are independent of each other.  We also:
   *
   *   - keep the accumulator 'best' in a register to avoid repeated
   *     loads/stores of table[i][j],
   *   - use pointer-based traversal in the k-loop to reduce index
   *     arithmetic and improve cache behavior.
   * -------------------------------------------------------------- */

  if (can_pair != NULL)
  {
    /* Version using precomputed can_pair[] table. */
#pragma scop
    for (int d = 1; d < _PB_N; ++d) {
      int max_i = _PB_N - d;         /* i runs from 0 to max_i-1 */
      for (int i = 0; i < max_i; ++i) {
        int j = i + d;

        /* Start from the current value (initially 0) for semantic fidelity. */
        DATA_TYPE best = T[i][j];

        /* Case 1: base j unpaired: use [i, j-1]. */
        DATA_TYPE v = T[i][j - 1];
        best = max_score(best, v);

        /* Case 2: base i unpaired: use [i+1, j]. */
        v = T[i + 1][j];
        best = max_score(best, v);

        /* Case 3: bases i and j both unpaired (central subsequence).   */
        DATA_TYPE v_center = T[i + 1][j - 1];
        best = max_score(best, v_center);  /* also covers the d == 1 case */

        /* For non-adjacent bases (d > 1), optionally pair i and j.     */
        if (d > 1) {
          DATA_TYPE pair_score = (DATA_TYPE)can_pair[(size_t)i * (size_t)N + (size_t)j];
          if (pair_score != (DATA_TYPE)0) {
            DATA_TYPE cand = v_center + pair_score;  /* add 1 when they can pair */
            best = max_score(best, cand);
          }
        }

        /* Case 4: bifurcation over split points k, with i < k < j.     */
        if (d > 1) {
          int k_count = d - 1;  /* number of k in (i, j) */

          /* Use pointer increments instead of repeated 2D indexing.
             left  traverses table[i][i+1 .. j-1]   along row i,
             right traverses table[i+2 .. j][j]     down column j. */
          DATA_TYPE *restrict left  = &T[i][i + 1];
          DATA_TYPE *restrict right = &T[i + 2][j];

          for (int kk = 0; kk < k_count; ++kk) {
            DATA_TYPE cand = *left + *right;
            best = max_score(best, cand);
            ++left;
            right += N;
          }
        }

        T[i][j] = best;
      }
    }
#pragma endscop
  }
  else
  {
    /* Fallback version: compute match(seq[i], seq[j]) on the fly if
       allocation for can_pair failed.  Semantics are identical to the
       original kernel, but with band-based traversal and scalar
       accumulation for better locality and vectorization. */
#pragma scop
    for (int d = 1; d < _PB_N; ++d) {
      int max_i = _PB_N - d;
      for (int i = 0; i < max_i; ++i) {
        int j = i + d;

        DATA_TYPE best = T[i][j];

        /* Case 1: base j unpaired */
        DATA_TYPE v = T[i][j - 1];
        best = max_score(best, v);

        /* Case 2: base i unpaired */
        v = T[i + 1][j];
        best = max_score(best, v);

        /* Case 3: central subsequence [i+1, j-1] */
        DATA_TYPE v_center = T[i + 1][j - 1];
        best = max_score(best, v_center);

        /* Only allow i,j to form a pair when they are non-adjacent (d > 1),
           as in the original code's "if (i < j-1)" condition. */
        if (d > 1) {
          DATA_TYPE cand = v_center + (DATA_TYPE)match(s[i], s[j]);
          best = max_score(best, cand);
        }

        /* Case 4: bifurcation at split points k, i < k < j. */
        if (d > 1) {
          int k_count = d - 1;

          DATA_TYPE *restrict left  = &T[i][i + 1];
          DATA_TYPE *restrict right = &T[i + 2][j];

          for (int kk = 0; kk < k_count; ++kk) {
            DATA_TYPE cand = *left + *right;
            best = max_score(best, cand);
            ++left;
            right += N;
          }
        }

        T[i][j] = best;
      }
    }
#pragma endscop
  }

  free(can_pair);
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(seq, base, N, n);
  POLYBENCH_2D_ARRAY_DECL(table, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_nussinov (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(table)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(seq);
  POLYBENCH_FREE_ARRAY(table);

  return 0;
}
