/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/*
  Original version by Dave Wonnacott at Haverford College <davew@cs.haverford.edu>,
  with help from Allison Lake, Ting Zhou, and Tian Jin,
  based on algorithm by Nussinov, described in Allison Lake's senior thesis.
*/
static
void kernel_nussinov[[gnu::flatten, gnu::noinline]](int n,
               base      POLYBENCH_1D(seq,N,n),
	       DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  /* Use local aliases to make the code clearer and help the compiler.
     POLYBENCH_2D(table,...) turns the parameter into a pointer to an
     n-column VLA, so table_ has type "DATA_TYPE (*)[n]". */
  base      *restrict seq_   = seq;
  DATA_TYPE (*restrict table_)[n] = table;

  int i, j, k, d;

  /* The original code traverses (i,j) in the order:
       for (i = n-1; i >= 0; --i)
         for (j = i+1; j < n; ++j)
     which is equivalent to processing all pairs (i,j) with i < j.

     Here we transform the iteration space to explicit "distance from the
     diagonal" d = j - i, and process increasing d:

       for d = 1 .. n-1
         for i = 0 .. n-d-1
           j = i + d

     For a fixed d, all (i,j) lie on the same anti-diagonal and are
     independent, because every dependency of table[i][j] refers only to
     entries with strictly smaller distance (d' < d).  This exposes
     more locality and allows safe parallelization across i.  We also
     keep the current best value for each (i,j) in a scalar "best",
     reducing redundant loads/stores of table[i][j].
  */

#pragma scop
  for (d = 1; d < _PB_N; ++d) {

    /* Number of valid i for this band: j = i + d < n  =>  i <= n - d - 1 */
    int max_i = _PB_N - d;

    /* Parallelize across i for each fixed distance d.
       - When compiled without OpenMP support, this pragma is ignored and
         the loop runs sequentially.
       - With -fopenmp, each band d is processed by multiple threads,
         and the implicit barrier at the end of the 'for' ensures that
         all updates for distance d complete before d+1 starts. */
#pragma omp parallel for schedule(static) private(j, k)
    for (i = 0; i < max_i; ++i) {
      j = i + d;

      /* Start from the current value (initialized to 0 in init_array).
         Keeping this in a register greatly reduces memory traffic
         compared to repeatedly reading/writing table_[i][j]. */
      DATA_TYPE best = table_[i][j];

      /* Case 1: j is unpaired -> use subsequence [i, j-1].
         In this transformed domain, j >= 1 always holds, so table_[i][j-1]
         is always in-bounds and the original "if (j-1 >= 0)" is redundant. */
      DATA_TYPE cand1 = table_[i][j - 1];
      best = max_score(best, cand1);

      /* Case 2: i is unpaired -> use subsequence [i+1, j].
         Here i+1 < n is guaranteed by the loop bounds, so the original
         "if (i+1 < n)" check is also redundant. */
      DATA_TYPE cand2 = table_[i + 1][j];
      best = max_score(best, cand2);

      /* Case 3: (i, j) form a pair (except that adjacent bases are not
         allowed to bond).

         Original code:
           if (j-1>=0 && i+1<n) {
             if (i<j-1)
               table[i][j] = max(table[i][j], table[i+1][j-1] + match(...));
             else
               table[i][j] = max(table[i][j], table[i+1][j-1]);
           }

         The guard (j-1>=0 && i+1<n) is always true here, so we only have
         to distinguish "i < j-1" from "i >= j-1".  Since j = i + d:

           i < j-1   <=>   i < i + d - 1   <=>   d > 1.

         For d == 1 (adjacent bases), table_[i+1][j-1] is in the lower
         triangle and remains 0 from initialization, so the "else" branch
         does not change best.  We keep the branch for clarity. */
      DATA_TYPE cand3 = table_[i + 1][j - 1];
      if (d > 1) {
        cand3 += (DATA_TYPE)match(seq_[i], seq_[j]);
      }
      /* For d == 1, cand3 == table_[i+1][i] == 0, so this max has no
         effect, matching the original behavior. */
      best = max_score(best, cand3);

      /* Case 4: Bifurcation at split point k, i < k < j.
         We compute:
             best = max(best, table_[i][k] + table_[k+1][j])  over k.

         This loop is the computational hot spot (O(n^3) overall).
         It is a pure max-reduction and has no loop-carried dependencies
         except through 'best', which allows reordering and unrolling.

         We manually unroll it by a factor of 4 to:
           - reduce loop-control overhead,
           - expose more instruction-level parallelism,
           - help the compiler's auto-vectorizer.

         The unrolling does not change the mathematical result because
         max_score is associative and commutative for these inputs. */

      int k_start = i + 1;
      int k_end   = j;   /* exclusive upper bound */

      /* Unrolled main part: handle 4 k's per iteration. */
      for (k = k_start; k + 3 < k_end; k += 4) {
        DATA_TYPE t0 = table_[i][k]     + table_[k + 1][j];
        DATA_TYPE t1 = table_[i][k + 1] + table_[k + 2][j];
        DATA_TYPE t2 = table_[i][k + 2] + table_[k + 3][j];
        DATA_TYPE t3 = table_[i][k + 3] + table_[k + 4][j];

        best = max_score(best, t0);
        best = max_score(best, t1);
        best = max_score(best, t2);
        best = max_score(best, t3);
      }

      /* Remainder loop: handle any leftover k values (0–3 iterations). */
      for (; k < k_end; ++k) {
        DATA_TYPE t = table_[i][k] + table_[k + 1][j];
        best = max_score(best, t);
      }

      /* Single write-back to memory. */
      table_[i][j] = best;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(seq, base, N, n);
  POLYBENCH_2D_ARRAY_DECL(table, DATA_TYPE, N, N, n, n);

