static
void kernel_nussinov[[gnu::flatten, gnu::noinline]](int n, base POLYBENCH_1D(seq,N,n),
			   DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  /* Indices:
   *   i: left endpoint of subsequence
   *   j: right endpoint of subsequence
   *   d: distance to diagonal (subsequence length difference), d = j - i
   *   k: split point for bifurcation
   */
  int i, j, k, d, ii;

  /* n is the true leading dimension of 'table' (VLA type table[n][n]).
   * _PB_N is PolyBench's loop bound (may allow subsampling).  We cap the
   * loop-bound with n to remain within the allocated matrix.
   */
  const int ld = n;             /* row/column stride for table (and logical size) */
  int n_pb = _PB_N;
  if (n_pb > n)
    n_pb = n;

  /* Tunable tile size for the i-dimension inside each band (anti-diagonal).
   * A small power of two typically gives good cache behavior on x64.
   */
  const int tile_i = 64;

#pragma scop
  /* Process the table by increasing distance d = j - i ("band" / anti-diagonal
   * order).  For fixed d, all cells (i, j = i + d) are independent because
   * each cell only depends on entries with strictly smaller distance.
   */
  for (d = 1; d < n_pb; ++d)
  {
    const int max_i = n_pb - d;

    /* Tile the i-dimension for better cache locality and to expose
     * coarse-grain parallelism.  Each tile covers a contiguous block
     * of rows along the current band.
     */
    #pragma omp parallel for schedule(static) if (max_i > tile_i)
    for (ii = 0; ii < max_i; ii += tile_i)
    {
      int i_end = ii + tile_i;
      if (i_end > max_i)
        i_end = max_i;

      for (i = ii; i < i_end; ++i)
      {
        j = i + d;

        /* Keep the current best score for interval [i, j] in a scalar
         * register; this avoids multiple loads/stores of table[i][j].
         * Initially table[i][j] is 0 (from init_array), but we read it
         * for semantic fidelity.
         */
        DATA_TYPE best = table[i][j];

        /* Case 1: base j is unpaired => subsequence [i, j-1]. */
        best = max_score(best, table[i][j-1]);

        /* Case 2: base i is unpaired => subsequence [i+1, j]. */
        best = max_score(best, table[i+1][j]);

        /* Case 3: consider pairing i with j.
         * Adjacent bases (j == i+1, i.e., d == 1) are not allowed to
         * bond; this matches the original i < j-1 condition.
         */
        {
          DATA_TYPE t_iplus1_jminus1 = table[i+1][j-1];

          if (d > 1)
          {
            /* Non-adjacent: add 0 or 1 depending on whether seq[i] and
             * seq[j] form a valid pair.
             */
            DATA_TYPE pair_score = (DATA_TYPE)match(seq[i], seq[j]);
            best = max_score(best, t_iplus1_jminus1 + pair_score);
          }
          else
          {
            /* Adjacent: we only propagate table[i+1][j-1] (which is a
             * lower-triangular base-case entry, initialized to 0).
             * This is exactly the original 'else' branch.
             */
            best = max_score(best, t_iplus1_jminus1);
          }
        }

        /* Case 4: bifurcation of interval [i, j] at every split point k
         * with i < k < j:
         *
         *   table[i][j] = max_k ( table[i][k] + table[k+1][j] )
         *
         * We express this as a simple max-reduction over k, using
         * pointers to make the memory-access pattern explicit:
         *
         *   - table[i][k] is contiguous along k (same row i).
         *   - table[k+1][j] advances with a constant stride 'ld'
         *     along the column j.
         */
        {
          DATA_TYPE *restrict row_i = table[i];   /* &table[i][0]       */
          DATA_TYPE *restrict col_j_from_ip1 =
              &table[i+1][j];                    /* &table[i+1][j]      */
          DATA_TYPE *restrict right = col_j_from_ip1;
          const int k_start = i + 1;
          const int k_end   = j;                 /* last k is j-1 */

          for (k = k_start; k < k_end; ++k)
          {
            DATA_TYPE cand = row_i[k] + *right;
            best = max_score(best, cand);

            /* Move down one row in column j: table[k+2][j] */
            right += ld;
          }
        }

        /* Single write-back to memory after all options considered. */
        table[i][j] = best;
      }
    }
  }
#pragma endscop

}


