static
void kernel_nussinov[[gnu::flatten, gnu::noinline]](int n, base POLYBENCH_1D(seq,N,n),
			   DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i, j, k, d;

  /* Local restrict-qualified pointers to help the optimizer.
   * The PolyBench macros declare VLA parameters:
   *   base seq[n];
   *   DATA_TYPE table[n][n];
   * which decay to these pointer types in expressions. */
  base *restrict seq_ = seq;
  DATA_TYPE (*restrict table_)[n] = table;

  /* Tile size for the i-dimension within each band (tunable). */
  const int TILE_I = 64;

