  /* Wavefront (band-based) dynamic program:
   *
   * We iterate by band distance d = j - i (1 .. N-1). For fixed d,
   * all cells (i, j = i + d) are independent because every dependency
   * of table[i][j] is to entries with strictly smaller distance.
   *
   * Within each band we:
   *   - tile the i-loop to improve cache locality,
   *   - keep a scalar accumulator 'best' per cell to avoid repeated
   *     loads/stores of table[i][j],
   *   - unroll the k-loop by 4 for the bifurcation term.
   */
  for (d = 1; d < _PB_N; ++d)
  {
    int max_i = _PB_N - d;       /* i ranges 0 .. max_i-1 for this band */

    /* Tile the i dimension in chunks of TILE_I.
     * This improves spatial locality for accesses along row i
     * (table_[i][*]) inside the k-loop. */
    for (int i0 = 0; i0 < max_i; i0 += TILE_I)
    {
      int i_end = i0 + TILE_I;
