        j = i + d;

        /* Start from current value (initialized to 0 in init_array). */
        DATA_TYPE best = table_[i][j];

        /* Case 1: j unpaired => use subsequence [i, j-1]. */
        DATA_TYPE cand = table_[i][j - 1];
        if (cand > best)
          best = cand;

        /* Case 2: i unpaired => use subsequence [i+1, j]. */
        cand = table_[i + 1][j];
        if (cand > best)
          best = cand;

        /* Case 3: pair (i, j) if they are not adjacent (d > 1).
         * For d == 1 (adjacent bases), the original code only added
         * table[i+1][j-1] which is a lower-triangular base case and
         * always 0, so skipping that case has no effect. */
        if (d > 1)
